const d=make({move:38206,index:-1,soul:true});observe((e,x)=>{if(e==='beforeUse'&&x.a.side===1){assert.equal(x.statusProbability(0),0);assert.ok(x.a.soulState.exposure4853);assert.equal(x.a.soulState.defeatEffectsSuppressed.sourceSoul,2038);x.a.build.resistance.minor='中毒';assert.throws(()=>x.ailment(x.a,'中毒',x.t,false,false,2),/Q-4853-003/);}},()=>turn(d));const e=make({move:38206,index:-1,soul:true});observe((event,x)=>{if(event==='beforeUse'&&x.a.side===1)x.statusProbability(51);},()=>turn(e));assert.equal(e.fighters[1].soulState.exposure4853,undefined);

